from __future__ import annotations

import re

_ALIGNMENTS = ("left", "right", "center")
_DELIMITER = re.compile(r":?-+:?")


def _cell_text(value) -> str:
    if value is None:
        return ""
    return str(value).replace("|", "\\|")


def _pad(text: str, width: int, align: str | None) -> str:
    extra = width - len(text)
    if extra <= 0:
        return text
    if align == "right":
        return " " * extra + text
    if align == "center":
        left = extra // 2
        return " " * left + text + " " * (extra - left)
    return text + " " * extra


def _delimiter(width: int, align: str | None) -> str:
    if align == "left":
        return ":" + "-" * (width - 1)
    if align == "right":
        return "-" * (width - 1) + ":"
    if align == "center":
        return ":" + "-" * (width - 2) + ":"
    return "-" * width


def _split_row(line: str) -> list[str]:
    """Split one table line into stripped cells, honouring ``\\|``."""
    line = line.strip()
    parts: list[str] = []
    current: list[str] = []
    i = 0
    while i < len(line):
        char = line[i]
        if char == "\\" and i + 1 < len(line) and line[i + 1] == "|":
            current.append("\\|")
            i += 2
        elif char == "|":
            parts.append("".join(current))
            current = []
            i += 1
        else:
            current.append(char)
            i += 1
    parts.append("".join(current))

    if line.startswith("|"):
        parts = parts[1:]
    if line.endswith("|") and not (len(line) > 1 and line[-2] == "\\"):
        parts = parts[:-1]

    return [part.strip() for part in parts]


def _parse_alignment(cell: str) -> str | None:
    if not _DELIMITER.fullmatch(cell):
        raise ValueError(f"invalid delimiter cell: {cell!r}")
    left = cell.startswith(":")
    right = cell.endswith(":")
    if left and right:
        return "center"
    if left:
        return "left"
    if right:
        return "right"
    return None


def format_table(
    header: list, rows: list[list], align: list[str | None] | None = None
) -> str:
    """Write a Markdown table."""
    columns = len(header)

    if align is None:
        alignments: list[str | None] = [None] * columns
    else:
        if not isinstance(align, list) or len(align) != columns:
            raise ValueError("align must have one entry per column")
        for value in align:
            if value is not None and value not in _ALIGNMENTS:
                raise ValueError(f"invalid alignment: {value!r}")
        alignments = list(align)

    header_cells = [_cell_text(value) for value in header]
    body_cells = []
    for row in rows:
        if len(row) > columns:
            raise ValueError("row has more cells than the header")
        cells = [_cell_text(value) for value in row]
        cells.extend([""] * (columns - len(cells)))
        body_cells.append(cells)

    widths = []
    for index in range(columns):
        width = max(3, len(header_cells[index]))
        for cells in body_cells:
            width = max(width, len(cells[index]))
        widths.append(width)

    def make_line(cells: list[str]) -> str:
        padded = [
            _pad(cell, widths[index], alignments[index])
            for index, cell in enumerate(cells)
        ]
        return "| " + " | ".join(padded) + " |"

    lines = [make_line(header_cells)]
    lines.append(
        "| "
        + " | ".join(
            _delimiter(widths[index], alignments[index])
            for index in range(columns)
        )
        + " |"
    )
    lines.extend(make_line(cells) for cells in body_cells)
    return "\n".join(lines)


def parse_table(
    text: str,
) -> tuple[list[str], list[list[str]], list[str | None]]:
    """Read a Markdown table into its header, rows, and alignments."""
    lines = text.splitlines()
    while lines and not lines[-1].strip():
        lines.pop()
    if len(lines) < 2:
        raise ValueError("table needs a header and a delimiter line")

    header = _split_row(lines[0])
    delimiter = _split_row(lines[1])
    if len(delimiter) != len(header):
        raise ValueError("delimiter line has a different number of cells")

    alignments = [_parse_alignment(cell) for cell in delimiter]

    rows = []
    for line in lines[2:]:
        row = [cell.replace("\\|", "|") for cell in _split_row(line)]
        if len(row) != len(header):
            raise ValueError("row has a different number of cells")
        rows.append(row)

    header = [cell.replace("\\|", "|") for cell in header]
    return header, rows, alignments
